  "Block variance component (random blocks)" = "مكوّن تباين القطاعات (قطاعات عشوائية)", "σ̂² = MS_E (error variance)" = "σ̂² = MS_E (تباين الخطأ)",
  "Press Run test to compute the test statistic and p-value." = "اضغط «شغّل الاختبار» لحساب إحصائية الاختبار والقيمة الاحتمالية.",
  "Not available" = "غير متاح", "Reject H0" = "رفض H0", "Fail to reject H0" = "عدم رفض H0", "Rejection region" = "منطقة الرفض", "Confidence interval" = "فترة الثقة", "P-value" = "القيمة الاحتمالية",
  "Decide each effect on its own with three methods: the rejection region, the confidence interval and the p-value. The table lists every effect; choose one below to see its decision, plots and effect plot." = "قرّر في كل أثر على حدة بثلاث طرق: منطقة الرفض وفترة الثقة والقيمة الاحتمالية. يسرد الجدول كل الآثار؛ اختر أثرًا أدناه لترى قراره ورسومه ومخطط أثره.",
  "Decide whether to reject H0 with three methods: the rejection region, the confidence interval and the p-value. With a 1 − α interval they normally lead to the same decision." = "قرّر هل تُرفض H0 بثلاث طرق: منطقة الرفض وفترة الثقة والقيمة الاحتمالية. وعند استخدام فترة بمستوى 1 − α تؤدي عادةً إلى القرار نفسه.",
  "All the effects" = "كل الآثار", "The line joins the mean of each level; the dots are the observations." = "يصل الخط بين متوسطات المستويات؛ والنقاط هي المشاهدات.",
  "Parallel lines mean no interaction; lines that cross or fan out mean the effect of one factor depends on the level of the other." = "الخطوط المتوازية تعني عدم وجود تفاعل؛ أما الخطوط المتقاطعة أو المتباعدة فتعني أن أثر أحد العاملين يعتمد على مستوى الآخر.",
  "An interaction is significant, so the main effects of the factors in it cannot be read alone: the post-hoc step compares levels within each level of the other factor (simple effects)." = "أحد التفاعلات دالّ، فلا يمكن قراءة الآثار الرئيسية للعوامل المشاركة فيه منفردة: تقارن الخطوة البعدية المستويات داخل كل مستوى من العامل الآخر (الآثار البسيطة).",
  "At least one effect is significant, so the next step finds which levels differ (post-hoc). The assumptions are checked after that." = "أحد الآثار على الأقل دالّ، فتحدّد الخطوة التالية أي المستويات تختلف (اختبار بعدي). ثم تُفحص الافتراضات.",
  "No effect is significant, so no post-hoc analysis is needed. The next step shows the ANOVA assumption checks, which tell whether the rank test was needed." = "لا أثر دالّ، فلا حاجة إلى اختبار بعدي. تعرض الخطوة التالية فحوص افتراضات تحليل التباين التي تبيّن هل كان اختبار الرتب لازمًا.",
  "No effect is significant, so no post-hoc analysis is needed. The next step checks the ANOVA assumptions." = "لا أثر دالّ، فلا حاجة إلى اختبار بعدي. تفحص الخطوة التالية افتراضات تحليل التباين.",
  "Treatment means against a scaled t distribution" = "متوسطات المعالجات مقابل توزيع t المُقيَّس",
  "The curve is a t distribution with the error degrees of freedom, scaled by √(MSE/n). Imagine sliding it along the axis: means that fit under the curve together are not different; a mean far outside it differs from the others." = "المنحنى توزيع t بدرجات حرية الخطأ، مُقيَّس بالمقدار √(MSE/n). تخيّل إزاحته على المحور: المتوسطات التي تقع معًا تحت المنحنى لا تختلف؛ والمتوسط البعيد عنه يختلف عن غيره.",
  "H0 is rejected, so the next step finds which treatments differ (post-hoc). The assumptions are checked after that." = "رُفضت H0، فتحدّد الخطوة التالية أي المعالجات تختلف (اختبار بعدي). ثم تُفحص الافتراضات.",
  "H0 is not rejected, so no post-hoc analysis is needed. The next step shows the ANOVA assumption checks, which tell whether the rank test was needed." = "لم تُرفض H0، فلا حاجة إلى اختبار بعدي. تعرض الخطوة التالية فحوص افتراضات تحليل التباين التي تبيّن هل كان اختبار الرتب لازمًا.",
  "H0 is not rejected, so no post-hoc analysis is needed. The next step checks the ANOVA assumptions." = "لم تُرفض H0، فلا حاجة إلى اختبار بعدي. تفحص الخطوة التالية افتراضات تحليل التباين.",
  "Treatments that share a letter are not significantly different." = "المعالجات التي تتشارك الحرف نفسه لا تختلف اختلافًا دالًّا.",
  "Comparisons with the control" = "المقارنات مع الشاهد", "Pairwise comparisons" = "المقارنات الزوجية", "Compared with the control" = "مقارنة بالشاهد", "Simultaneous intervals for the differences" = "فترات متزامنة للفروق",
  " Dunnett's test needs a control, so Tukey HSD is used here." = " يحتاج اختبار دانيت إلى شاهد، لذا يُستخدم هنا اختبار توكي HSD.",
  "At least one effect is significant, so find which levels differ: the levels of a factor for a significant main effect, and the simple effects for a significant interaction." = "أحد الآثار على الأقل دالّ، فحدّد أي المستويات تختلف: مستويات العامل للأثر الرئيسي الدالّ، والآثار البسيطة للتفاعل الدالّ.",
  "H0 was rejected, so find which pairs of treatments differ." = "رُفضت H0، فحدّد أي أزواج المعالجات تختلف.", "Significant effect" = "الأثر الدالّ", "Method" = "الطريقة",
  "compares the groups through the ranks of all the observations" = "يقارن المجموعات عبر رتب جميع المشاهدات",
  "ranks the responses within each block, so differences between blocks cannot affect it" = "يرتّب الاستجابات داخل كل قطاع، فلا تؤثر فيه الفروق بين القطاعات",
  "ranks all the observations together and tests each factor and each interaction on the ranks" = "يرتّب جميع المشاهدات معًا ويختبر كل عامل وكل تفاعل على الرتب",
  "ranks the treatment combinations within each block and tests each factor and each interaction on the rank sums" = "يرتّب توليفات المعالجات داخل كل قطاع ويختبر كل عامل وكل تفاعل على مجاميع الرتب",
  "removes the blocking factors, ranks the residuals and tests each factor and each interaction on the ranks (Quade's test)" = "يزيل عوامل التقطيع ويرتّب البواقي ويختبر كل عامل وكل تفاعل على الرتب (اختبار كويد)",
  "removes the blocking factors (rows and columns, and Greek letters) and compares the treatments through the ranks of the residuals (Quade's test)" = "يزيل عوامل التقطيع (الصفوف والأعمدة والحروف اليونانية) ويقارن المعالجات عبر رتب البواقي (اختبار كويد)",
  "Check the three ANOVA assumptions on the residuals: normality, constant variance (Breusch-Pagan) and independence." = "افحص افتراضات تحليل التباين الثلاثة على البواقي: الطبيعية وثبات التباين (بروش-باغان) والاستقلالية.",
  "Not required" = "غير لازم", "Not satisfied" = "غير محقق", "Satisfied" = "محقق", "Normal QQ plot of the residuals" = "مخطط QQ الطبيعي للبواقي", "Histogram of the residuals" = "المدرج التكراري للبواقي",
  "Constant variance of the residuals" = "ثبات تباين البواقي", "Residuals versus fitted values" = "البواقي مقابل القيم المقدَّرة", "Normality" = "الطبيعية", "Independence" = "الاستقلالية",
  "Not required: the Welch ANOVA does not assume equal variances, so this check does not apply. The plots are shown for reference." = "غير لازم: لا يفترض تحليل ويلش تساوي التباينات، فلا ينطبق هذا الفحص. تُعرض الرسوم للاطلاع فقط.",
  "the model terms" = "حدود النموذج",
  "the fitted values; with a term for every combination and two replicates, the usual version would reject whatever the data" = "القيم المقدَّرة؛ فمع وجود حد لكل توليفة ومكرَّرين فإن الصيغة المعتادة سترفض مهما كانت البيانات"
)

ar_tpl(
  "Shapiro-Wilk at α = %s: p ≥ α means no evidence against normality." = "اختبار شابيرو-ويلك عند α = $1: القيمة p ≥ α تعني عدم وجود دليل ضد الطبيعية.",
  "No evidence of correlation between consecutive observations (p ≥ %s), in the order the data are listed." = "لا دليل على ارتباط بين المشاهدات المتتالية (p ≥ $1)، بحسب ترتيب إدراج البيانات.",
  "H0: all %d groups have the same variance. The %s decides (p %s %s)%s, so the %s is used." = "H0: لجميع المجموعات الـ$1 التباين نفسه. يحسم $2 الأمر (p $3 $4)$5، لذا يُستخدم $6.",
  "; you chose to assume %s variances" = "؛ وقد اخترت افتراض أن التباينات $1",
  "The %s decides: %s." = "يحسم $1 الأمر: $2.",
  "Test used: %s. %s" = "الاختبار المستخدم: $1. $2", "Suggested test: %s. %s" = "الاختبار المقترح: $1. $2",
  "Rows and columns are blocking factors. The Latin letters are the treatments being tested; the Greek letters (%s) have their own F test in the table." = "الصفوف والأعمدة عوامل تقطيع. الحروف اللاتينية هي المعالجات المختبَرة؛ وللحروف اليونانية ($1) اختبار F خاص بها في الجدول.",
  "Blocking %s: a relative efficiency %s 1 means the blocked design is more precise than a completely randomized one." = "التقطيع $1: الكفاءة النسبية $2 1 تعني أن التصميم المقطَّع أدق من التصميم العشوائي الكامل.",
  "With random blocks, E(MS_Blocks) = σ² + aσ²β, where a = %d treatments, which gives the estimator above." = "مع القطاعات العشوائية، E(MS_Blocks) = σ² + aσ²β، حيث a = $1 معالجات، وهذا يعطي المقدِّر أعلاه.",
  "Each effect: %s" = "كل أثر: $1", "Ranks of the levels of %s" = "رتب مستويات $1", "Test statistic (%s)" = "إحصائية الاختبار ($1)",
  "Significant at α = %s: %s." = "دالّ عند α = $1: $2.", "Effect plot: %s" = "مخطط الأثر: $1",
  "Each treatment is compared with the control (%s)." = "تُقارن كل معالجة بالشاهد ($1).",
  "The levels of %s are compared two by two; levels that share a letter are not significantly different." = "تُقارن مستويات $1 اثنين اثنين؛ والمستويات التي تتشارك الحرف نفسه لا تختلف اختلافًا دالًّا.",
  "The problem names a control group (%s), so Dunnett's test, which compares every treatment with the control, is offered and suggested." = "تحدّد المسألة مجموعة شاهد ($1)، لذا يُعرض اختبار دانيت الذي يقارن كل معالجة بالشاهد، ويُقترح.",
  "No effect is significant at α = %s, so no post-hoc analysis is carried out." = "لا أثر دالّ عند α = $1، فلا يُجرى تحليل بعدي.",
  "H0 was not rejected (%s ≥ α = %s), so no post-hoc analysis is carried out." = "لم تُرفض H0 ($1 ≥ α = $2)، فلا يُجرى تحليل بعدي.",
  "H0: the residuals come from a normal distribution. p ≥ %s means no evidence against normality." = "H0: البواقي مأخوذة من توزيع طبيعي. القيمة p ≥ $1 تعني عدم وجود دليل ضد الطبيعية.",
  "H0: the residuals have constant variance (Breusch-Pagan test: the squared residuals regressed on %s). p ≥ %s means the spread can be treated as constant." = "H0: للبواقي تباين ثابت (اختبار بروش-باغان: مربعات البواقي منحدرة على $1). القيمة p ≥ $2 تعني أنه يمكن اعتبار التشتت ثابتًا."
)
